import Foundation

/// Finite local-development limits. Runtime, cleanup and generated bytes are independent of the 8 MiB retained tail.
public struct ProcessPolicy: Codable, Sendable {
    public let name: String
    public let runtimeSeconds: UInt32
    public let cleanupSeconds: UInt32
    public let generatedOutputBytes: UInt64
    public init(name: String, runtimeSeconds: UInt32, cleanupSeconds: UInt32, generatedOutputBytes: UInt64) {
        self.name = name; self.runtimeSeconds = runtimeSeconds
        self.cleanupSeconds = cleanupSeconds; self.generatedOutputBytes = generatedOutputBytes
    }
    public static let toolInspection = ProcessPolicy(name: "local-tool-inspection", runtimeSeconds: 30, cleanupSeconds: 60, generatedOutputBytes: 64 << 20)
    public static let developmentBuild = ProcessPolicy(name: "local-development-build", runtimeSeconds: 1800, cleanupSeconds: 60, generatedOutputBytes: 1 << 30)
    public static let localValidation = ProcessPolicy(name: "local-validation", runtimeSeconds: 120, cleanupSeconds: 60, generatedOutputBytes: 256 << 20)
    public static let simulatorManagement = ProcessPolicy(name: "local-simulator-management", runtimeSeconds: 120, cleanupSeconds: 60, generatedOutputBytes: 64 << 20)
}

enum CommandStream: String, CaseIterable, Codable { case stdout, stderr }
enum StreamObservation { case pending, eof, bytes(Data) }
enum LaunchReadiness { case pending, ready, failed(Int32) }
struct OwnedLaunch { let pid: Int32; let setupError: Int32 }
protocol OwnedCommandControl: AnyObject {
    func monotonicNow() throws -> UInt64
    func launch(command: [String], directory: URL?, environment: [String: String]) throws -> OwnedLaunch
    func readiness() throws -> LaunchReadiness
    func release() throws
    func read(_ stream: CommandStream) throws -> StreamObservation
    func exitedWithoutReaping() throws -> Bool
    func killOwnedGroup() throws
    func reap() throws -> Int32?
    func groupAbsent() throws -> Bool
    func pause() throws
    func close() throws
}

struct CommandCustodyReceipt: Codable {
    var schema = "mixer.owned-command.2"
    var retainedInputDirectories: [String] = []
    let command: [String]
    let directory: String?
    let policy: ProcessPolicy
    let aggregateLimit: UInt64
    let aggregatePreviouslyGenerated: UInt64
    var state = "INTENT"
    var pid: Int32?
    var ownedPGID: Int32?
    var ownedSession: Int32?
    var runtimeStartedNS: UInt64 = 0
    var cleanupStartedNS: UInt64?
    var terminalNS: UInt64?
    var released = false
    var groupKillSent = false
    var directChildReaped = false
    var stdoutEOF = false
    var stderrEOF = false
    var ownedGroupAbsent = false
    var descriptorsClosed = false
    var terminalCustody = false
    var exitCode: Int32?
    var generatedBytes: UInt64 = 0
    var stdoutBytes: UInt64 = 0
    var stderrBytes: UInt64 = 0
    var outputTruncated = false
    var stopReason: String?
    var uncertainty: String?
    var terminalFactsComplete: Bool {
        directChildReaped && stdoutEOF && stderrEOF && ownedGroupAbsent && descriptorsClosed
    }
}
struct UnknownCommandCustody: Error, CustomStringConvertible {
    let description: String
}

struct CommandTail {
    static let capacity = 8 * 1_048_576
    private var storage = [UInt8](repeating: 0, count: capacity)
    private var position = 0
    private(set) var count = 0
    mutating func append(_ data: Data) {
        let bytes = data.suffix(Self.capacity)
        let first = min(bytes.count, Self.capacity - position)
        storage.replaceSubrange(position..<(position + first), with: bytes.prefix(first))
        if bytes.count > first { storage.replaceSubrange(0..<(bytes.count - first), with: bytes.dropFirst(first)) }
        position = (position + bytes.count) % Self.capacity
        count = min(Self.capacity, count + bytes.count)
    }
    var data: Data {
        let beginning = (position - count + Self.capacity) % Self.capacity
        let first = min(count, Self.capacity - beginning)
        var result = Data(storage[beginning..<(beginning + first)])
        if count > first { result.append(contentsOf: storage[0..<(count - first)]) }
        return result
    }
}

final class OwnedCommandExecution {
    private(set) var receipt: CommandCustodyReceipt
    private let control: any OwnedCommandControl
    private let save: (CommandCustodyReceipt) throws -> Void
    private var tail = CommandTail()
    private var previousTime: UInt64 = 0
    init(command: [String], directory: URL?, policy: ProcessPolicy, aggregateLimit: UInt64,
         aggregateUsed: UInt64, retainedInputs: [URL] = [], control: any OwnedCommandControl, save: @escaping (CommandCustodyReceipt) throws -> Void) {
        receipt = CommandCustodyReceipt(command: command, directory: directory?.path, policy: policy,
            aggregateLimit: aggregateLimit, aggregatePreviouslyGenerated: aggregateUsed)
        receipt.retainedInputDirectories = retainedInputs.map { $0.path }
        self.control = control; self.save = save
    }
    private func now() throws -> UInt64 {
        let value = try control.monotonicNow()
        guard value >= previousTime else { throw MixerFailure("process.clock", "Monotonic clock moved backwards") }
        previousTime = value; return value
    }
    private func add(_ a: UInt64, _ b: UInt64) throws -> UInt64 {
        let (sum, overflow) = a.addingReportingOverflow(b)
        guard !overflow else { throw MixerFailure("process.accounting", "Command accounting overflow") }
        return sum
    }
    private func drain(_ stream: CommandStream) throws {
        if stream == .stdout ? receipt.stdoutEOF : receipt.stderrEOF { return }
        switch try control.read(stream) {
        case .pending: break
        case .eof:
            if stream == .stdout { receipt.stdoutEOF = true } else { receipt.stderrEOF = true }
        case .bytes(let bytes):
            guard !bytes.isEmpty else { throw MixerFailure("process.stream", "Empty data is not an EOF observation") }
            receipt.generatedBytes = try add(receipt.generatedBytes, UInt64(bytes.count))
            if stream == .stdout { receipt.stdoutBytes = try add(receipt.stdoutBytes, UInt64(bytes.count)) }
            else { receipt.stderrBytes = try add(receipt.stderrBytes, UInt64(bytes.count)) }
            tail.append(bytes)
            receipt.outputTruncated = receipt.generatedBytes > UInt64(CommandTail.capacity)
        }
    }
    func execute(directory: URL?, environment: [String: String]) throws -> CommandResult {
        do {
            receipt.runtimeStartedNS = try now()
            let runtimeEnd = try add(receipt.runtimeStartedNS, UInt64(receipt.policy.runtimeSeconds) * 1_000_000_000)
            try save(receipt)
            let launched = try control.launch(command: receipt.command, directory: directory, environment: environment)
            receipt.pid = launched.pid > 1 ? launched.pid : nil
            receipt.state = "FORKED_GATE_CLOSED"; try save(receipt)
            guard launched.pid > 1, launched.setupError == 0 else {
                throw MixerFailure("process.launch", "Launch/parent pipe setup failed: errno \(launched.setupError)")
            }
            var ready = false
            while !ready {
                guard try now() < runtimeEnd else { throw MixerFailure("process.launch", "Deadline before session readiness") }
                switch try control.readiness() {
                case .pending: try control.pause()
                case .failed(let code): throw MixerFailure("process.launch", "Session/cwd/descriptor setup failed: errno \(code)")
                case .ready: ready = true
                }
            }
            receipt.ownedPGID = launched.pid; receipt.ownedSession = launched.pid
            receipt.state = "OWNED_GATE_CLOSED"; try save(receipt)
            try control.release()
            receipt.released = true; receipt.state = "RUNNING"; try save(receipt)
            var cleanupEnd: UInt64?
            while true {
                let instant = try now()
                if let end = cleanupEnd, instant >= end {
                    throw MixerFailure("process.cleanup", "Cleanup budget expired without terminal custody")
                }
                try drain(.stdout); try drain(.stderr)
                if cleanupEnd == nil {
                    let total = try add(receipt.aggregatePreviouslyGenerated, receipt.generatedBytes)
                    if receipt.generatedBytes > receipt.policy.generatedOutputBytes { receipt.stopReason = "generated-output-limit" }
                    else if total > receipt.aggregateLimit { receipt.stopReason = "aggregate-output-limit" }
                    else if instant >= runtimeEnd { receipt.stopReason = "runtime-deadline" }
                    let childExited = try control.exitedWithoutReaping()
                    if receipt.stopReason != nil || childExited {
                        receipt.cleanupStartedNS = instant
                        cleanupEnd = try add(instant, UInt64(receipt.policy.cleanupSeconds) * 1_000_000_000)
                        receipt.state = "CLEANUP_REQUESTED"; try save(receipt)
                        // A naturally exited leader needs no signal. Reap it before absence-only observations.
                        // A live leader can exit during a deadline signal; any uncertainty freezes this context.
                        if !childExited {
                            try control.killOwnedGroup()
                            receipt.groupKillSent = true
                        }
                        receipt.state = "CLEANING"; try save(receipt)
                    }
                }
                if cleanupEnd != nil {
                    if !receipt.directChildReaped, let code = try control.reap() {
                        receipt.exitCode = code; receipt.directChildReaped = true
                    }
                    if receipt.directChildReaped && !receipt.ownedGroupAbsent {
                        receipt.ownedGroupAbsent = try control.groupAbsent()
                    }
                    if receipt.directChildReaped && receipt.stdoutEOF && receipt.stderrEOF && receipt.ownedGroupAbsent {
                        try control.close(); receipt.descriptorsClosed = true
                        receipt.state = "TERMINAL"; receipt.terminalNS = try now()
                        receipt.terminalCustody = receipt.terminalFactsComplete
                        // Recheck budgets after the final drain, including output generated during cleanup.
                        if receipt.stopReason == nil {
                            if receipt.generatedBytes > receipt.policy.generatedOutputBytes { receipt.stopReason = "generated-output-limit" }
                            else if try add(receipt.aggregatePreviouslyGenerated, receipt.generatedBytes) > receipt.aggregateLimit {
                                receipt.stopReason = "aggregate-output-limit"
                            }
                        }
                        try save(receipt); break
                    }
                }
                try control.pause()
            }
        } catch {
            receipt.state = "UNKNOWN"; receipt.terminalCustody = false; receipt.uncertainty = String(describing: error)
            // Filesystem persistence only: no process, pipe, wait, probe, or signal operation follows uncertainty.
            do { try save(receipt) } catch { receipt.uncertainty = (receipt.uncertainty ?? "Unknown custody") + "; HOLD persistence failed: \(error)" }
            throw UnknownCommandCustody(description: receipt.uncertainty ?? "Unknown command custody")
        }
        if let reason = receipt.stopReason { throw MixerFailure("process.\(reason)", "Command stopped with terminal custody: \(reason)") }
        return CommandResult(command: receipt.command, exitCode: receipt.exitCode!,
            output: String(decoding: tail.data, as: UTF8.self), outputTruncated: receipt.outputTruncated)
    }
}
